function renderCanvas(item,type="image/png",quality=1){return new Promise((resolve,reject)=>{const s=sizeMmFor(item),svgBlob=new Blob([renderLabelSvg(item,{uid:`render-${Date.now()}-${Math.random()}`})],{type:"image/svg+xml;charset=utf-8"}),url=URL.createObjectURL(svgBlob),img=new Image();img.onload=()=>{const c=document.createElement("canvas");c.width=mmToPx(s.w);c.height=mmToPx(s.h);const ctx=c.getContext("2d");if(type==="image/jpeg"){ctx.fillStyle="#ffffff";ctx.fillRect(0,0,c.width,c.height)}else ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);c.toBlob(blob=>blob?resolve({blob,width:c.width,height:c.height,wMm:s.w,hMm:s.h}):reject(new Error("Export canvas impossible")),type,quality)};img.onerror=reject;img.src=url})}
async function labelPngBytes(item){const rendered=await renderCanvas(item,"image/png",1);return blobToBytes(rendered.blob)}
