function pdfBytes(pages){const pt=72/25.4,objects=[];function add(body){objects.push(typeof body==="string"?asciiBytes(body):body);return objects.length}add("<< /Type /Catalog /Pages 2 0 R >>");const pagesId=add(""),pageIds=[],pending=[];pages.forEach(page=>{const pageId=add(""),imgIds=[];page.images.forEach(img=>{imgIds.push(add(concatBytes([asciiBytes(`<< /Type /XObject /Subtype /Image /Width ${img.width} /Height ${img.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${img.bytes.length} >>\nstream\n`),img.bytes,asciiBytes("\nendstream")])))});const contentId=add("");pageIds.push(pageId);pending.push({page,pageId,imgIds,contentId})});objects[pagesId-1]=asciiBytes(`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(" ")}] /Count ${pages.length} >>`);pending.forEach(entry=>{const p=entry.page,w=p.wMm*pt,h=p.hMm*pt,res=entry.imgIds.map((id,i)=>`/Im${i} ${id} 0 R`).join(" "),imageOps=p.images.map((img,i)=>{const x=img.xMm*pt,y=(p.hMm-img.yMm-img.hMm)*pt,iw=img.wMm*pt,ih=img.hMm*pt;return`q ${iw.toFixed(3)} 0 0 ${ih.toFixed(3)} ${x.toFixed(3)} ${y.toFixed(3)} cm /Im${i} Do Q`}).join("\n"),guideOps=p.guides?p.images.map(img=>{const x=img.xMm*pt,y=(p.hMm-img.yMm-img.hMm)*pt,r=(img.xMm+img.wMm)*pt,t=(p.hMm-img.yMm)*pt,l=4*pt;return`0.35 w 0.35 0.25 0.2 RG ${x-l} ${y} m ${x} ${y} l S ${x} ${y-l} m ${x} ${y} l S ${r} ${y-l} m ${r} ${y} l S ${r} ${y} m ${r+l} ${y} l S ${x-l} ${t} m ${x} ${t} l S ${x} ${t} m ${x} ${t+l} l S ${r} ${t} m ${r+l} ${t} l S ${r} ${t} m ${r} ${t+l} l S`}).join("\n"):"",ops=[imageOps,guideOps].filter(Boolean).join("\n");objects[entry.pageId-1]=asciiBytes(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 ${w.toFixed(3)} ${h.toFixed(3)}] /Resources << /XObject << ${res} >> >> /Contents ${entry.contentId} 0 R >>`);objects[entry.contentId-1]=asciiBytes(`<< /Length ${ops.length} >>\nstream\n${ops}\nendstream`)});const chunks=[asciiBytes("%PDF-1.4\n%\xE2\xE3\xCF\xD3\n")],offsets=[0];objects.forEach((obj,i)=>{offsets.push(chunks.reduce((s,c)=>s+c.length,0));chunks.push(asciiBytes(`${i+1} 0 obj\n`),obj,asciiBytes("\nendobj\n"))});const xrefAt=chunks.reduce((s,c)=>s+c.length,0);let xref=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;for(let i=1;i<offsets.length;i++)xref+=`${String(offsets[i]).padStart(10,"0")} 00000 n \n`;xref+=`trailer << /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xrefAt}\n%%EOF`;chunks.push(asciiBytes(xref));return concatBytes(chunks)}async function singleLabelPdfBytes(item){const img=await labelJpeg(item);return pdfBytes([{wMm:img.wMm,hMm:img.hMm,images:[{...img,xMm:0,yMm:0}]}])}
async function combinedPdfBytes(items,formatKey="a4"){const format=paperFormats[formatKey]||paperFormats.a4,bleed=clamp(printSettings.bleed,0,10,2),margin=Math.max(6,bleed+4),gap=Math.max(2,bleed*2+2),pages=[],usableW=format.w-margin*2,usableH=format.h-margin*2,ordered=[...items].sort((a,b)=>Number(b.heightMm)-Number(a.heightMm));let page={wMm:format.w,hMm:format.h,images:[],guides:printSettings.showCutGuides},x=margin,y=margin,rowH=0;for(const item of ordered){const img=await labelJpeg(item);if(x>margin&&x+img.wMm>format.w-margin){x=margin;y+=rowH+gap;rowH=0}if(y>margin&&y+img.hMm>format.h-margin){pages.push(page);page={wMm:format.w,hMm:format.h,images:[],guides:printSettings.showCutGuides};x=margin;y=margin;rowH=0}const scale=Math.min(1,usableW/img.wMm,usableH/img.hMm),placed={...img,wMm:img.wMm*scale,hMm:img.hMm*scale,xMm:x,yMm:y};page.images.push(placed);x+=placed.wMm+gap;rowH=Math.max(rowH,placed.hMm)}if(page.images.length)pages.push(page);return pdfBytes(pages)}
function crcTable(){let table=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;table[n]=c>>>0}return table}const crcLookup=crcTable();function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcLookup[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
function u16(v){const b=new Uint8Array(2);new DataView(b.buffer).setUint16(0,v,true);return b}function u32(v){const b=new Uint8Array(4);new DataView(b.buffer).setUint32(0,v,true);return b}
function makeZip(files){const locals=[],centrals=[];let offset=0;files.forEach(file=>{const name=asciiBytes(file.name),data=file.data,crc=crc32(data),local=concatBytes([u32(0x04034b50),u16(20),u16(0),u16(0),u16(0),u16(0),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),name,data]);locals.push(local);centrals.push(concatBytes([u32(0x02014b50),u16(20),u16(20),u16(0),u16(0),u16(0),u16(0),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),name]));offset+=local.length});const centralSize=centrals.reduce((s,c)=>s+c.length,0),end=concatBytes([u32(0x06054b50),u16(0),u16(0),u16(files.length),u16(files.length),u32(centralSize),u32(offset),u16(0)]);return new Blob([...locals,...centrals,end],{type:"application/zip"})}
async function exportZipPng(){if(!validatedDesigns.length)return setExportStatus("Aucun design valide a exporter.");setExportStatus("Generation des PNG HD...");const files=[];for(let i=0;i<validatedDesigns.length;i++)files.push({name:`${String(i+1).padStart(2,"0")}-${safeName(validatedDesigns[i].name,"png")}`,data:await labelPngBytes(validatedDesigns[i])});downloadBlob(makeZip(files),"designs-potions-png.zip");setExportStatus("ZIP PNG HD cree.")}
async function exportZipPdf(){if(!validatedDesigns.length)return setExportStatus("Aucun design valide a exporter.");setExportStatus("Generation des PDF HD...");const files=[];for(let i=0;i<validatedDesigns.length;i++)files.push({name:`${String(i+1).padStart(2,"0")}-${safeName(validatedDesigns[i].name,"pdf")}`,data:await singleLabelPdfBytes(validatedDesigns[i])});downloadBlob(makeZip(files),"designs-potions-pdf.zip");setExportStatus("ZIP PDF HD cree.")}
async function exportSinglePdf(){if(!validatedDesigns.length)return setExportStatus("Aucun design valide à exporter.");const formatKey=$("#paperFormat")?.value||"a4",format=paperFormats[formatKey]||paperFormats.a4;printSettings.format=formatKey;syncPrintInputs();setExportStatus(`Génération du PDF optimisé en ${format.name} paysage…`);downloadBlob(new Blob([await combinedPdfBytes(validatedDesigns,formatKey)],{type:"application/pdf"}),`designs-potions-planche-${format.name.toLowerCase()}.pdf`);setExportStatus(`PDF ${format.name} créé avec polices intégrées${printSettings.showCutGuides?" et traits de coupe":""}.`);scheduleSave()}
